// Rust guideline compliant 2026-02-21
//! Shared number vectors, generated by `tests/fixtures/canonical-numbers/generate.py`.

use integrity_canonical::canonical_json_from_bytes;
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!(
        "../../../tests/fixtures/canonical-numbers/vectors.json"
    ))
    .expect("shared fixture must be valid JSON")
}

#[test]
fn numbers_match_the_shared_oracle() {
    let vectors = fixture();
    for case in vectors["valid"].as_array().expect("valid cases") {
        let input = case[0].as_str().expect("input");
        let bytes = canonical_json_from_bytes(input.as_bytes())
            .unwrap_or_else(|error| panic!("{input} must canonicalize: {error}"));
        assert_eq!(
            std::str::from_utf8(&bytes).unwrap(),
            case[1].as_str().unwrap(),
            "{input}"
        );
    }
    for case in vectors["invalid"].as_array().expect("invalid cases") {
        let input = case.as_str().expect("input");
        assert!(
            canonical_json_from_bytes(input.as_bytes()).is_err(),
            "{input} must refuse"
        );
    }
}
